/*
 * Importação dos kanjis N5 de joyokanjikai.com + correções de dados.
 * Proposta e lista completa: docs/importacao-n5-joyokanjikai.md
 * Grava as mesmas colunas que o cadastro do professor (VocabularyRepository.AddWordAsync/UpdateWordAsync
 * e KanjiRepository.UpdateAsync). Os blocos rodam numa transação só: qualquer passo que não afete exatamente
 * 1 linha (ou o número esperado) gera erro, o isql (-b) para e nada é gravado.
 * São vários EXECUTE BLOCK porque o Firebird limita cada um a 256 contextos.
 * Rodar com: isql -b -ch UTF8 -i kanjis-n5-joyokanjikai.sql <banco>
 */
SET SQL DIALECT 3;
SET TERM ^ ;
EXECUTE BLOCK AS
BEGIN
  /* 1. Assuntos novos */
  INSERT INTO SUBJECTS (SBJ_ID, SBJ_NAME) VALUES (NEXT VALUE FOR SUBJECTS_ID_GEN, 'direções');
  IF (ROW_COUNT <> 1) THEN EXECUTE STATEMENT 'FALHOU_assunto_direcoes';
  INSERT INTO SUBJECTS (SBJ_ID, SBJ_NAME) VALUES (NEXT VALUE FOR SUBJECTS_ID_GEN, 'conceitos');
  IF (ROW_COUNT <> 1) THEN EXECUTE STATEMENT 'FALHOU_assunto_conceitos';

  /* Todos os assuntos usados abaixo precisam existir (a FK aceitaria NULL). */
  IF ((SELECT COUNT(*) FROM SUBJECTS WHERE SBJ_NAME IN ('contagem', 'lugares', 'escritório', 'direções', 'tempo', 'natureza', 'conceitos', 'saúde', 'verbos', 'pessoas', 'escola', 'advérbios', 'adjetivos', 'cores', 'estação', 'países')) <> 16) THEN EXECUTE STATEMENT 'FALHOU_assunto_inexistente';

  /* 2. Leitura de kanjis: 28 kanjis passam a N5 (23 sem nível, 4 em N4 e o 車 em 'n5') */
  UPDATE KANJI SET KNJ_JLPT = 'N5' WHERE KNJ_JLPT IS DISTINCT FROM 'N5' AND KNJ_KANJI IN ('北', '南', '花', '魚', '空', '目', '口', '耳', '手', '足', '言', '飲', '会', '買', '立', '古', '高', '安', '多', '新', '少', '長', '週', '店', '道', '車', '駅', '社');
  IF (ROW_COUNT <> 28) THEN EXECUTE STATEMENT 'FALHOU_niveis_kanji';
END^
